import React from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import Home from './pages/Home';
import Dashboard from './pages/Dashboard';
import ManageParticipants from './pages/ManageParticipants';
import ManageJuries from './pages/ManageJuries';
import ManageQuestions from './pages/ManageQuestions';
import SimultaneousEvaluation from './pages/SimultaneousEvaluation';
import Navbar from './components/Navbar';
import './App.css';

function App() {
  return (
    <Router>
      <Navbar />
      <div className="container">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/manage-participants" element={<ManageParticipants />} />
          <Route path="/manage-juries" element={<ManageJuries />} />
          <Route path="/manage-questions" element={<ManageQuestions />} />
          <Route path="/evaluation-simultaneous" element={<SimultaneousEvaluation />} />
          <Route path="/evaluation" element={<SimultaneousEvaluation />} />
          <Route path="/dashboard" element={<Dashboard />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
